class Key(str):
 def __hash__(self): return 17
 def __eq__(self,other):
  events.append((str.__str__(self),str.__str__(other)))
  return str.__eq__(self,other)
source={Key(str(i)):i for i in range(2)}
for i in range(0):source.popitem()
for i in []:del source[Key(str(i))]
events.clear()
target={}
target.update(source)
result=(events,list(target.items()),list(source.items()))

